/**
 * Jinx Kazali + Marionette: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Kazali
 * Wiki: https://wiki.bloodontheclocktower.com/Marionette
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { analyseSetup } from '#lib/core/rules/setup.ts';

describe('Kazali + Marionette jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'kazali', 'marionette');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('kazali')?.name).toBe('Kazali');
		expect(data.byId.get('marionette')?.name).toBe('Marionette');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['kazali', 'marionette'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['kazali'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['marionette'])).not.toContain(jinx);
	});

	// The Kazali deals no Minions; the Marionette enters play after it as its neighbour, so it
	// is neither counted nor given a good token of its own (M22).
	it('leaves the Marionette out of the setup counts', () => {
		const get = (...ids: string[]) => ids.map((id) => data.byId.get(id)!);
		const result = analyseSetup({
			players: 7,
			inPlay: get('kazali', 'marionette', 'chef', 'empath', 'monk', 'mayor', 'saint', 'butler')
		});
		expect(result.notDealt).toContain('marionette');
		expect(result.warnings.filter((w) => w.code !== 'player-count')).toEqual([]);
	});
});
